CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity, and the address an invitation is matched against when an external attendee later signs up.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name shown on invitations and in the attendee list.
	"full_name" VARCHAR(160) NOT NULL,
	-- IANA zone such as Europe/Berlin. The default for new events and the zone the grid is drawn in, but never the zone an existing event is interpreted with.
	"default_timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person who owns calendars and answers invitations. The zone here is a display preference; the authoritative zone for any given event lives on the event, because moving house must not shift a meeting.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity, and the address an invitation is matched against when an external attendee later signs up.';
COMMENT ON COLUMN "users"."full_name" IS 'Display name shown on invitations and in the attendee list.';
COMMENT ON COLUMN "users"."default_timezone" IS 'IANA zone such as Europe/Berlin. The default for new events and the zone the grid is drawn in, but never the zone an existing event is interpreted with.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "calendars" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning account. A resource calendar is owned by whoever administers it.
	"owner_id" BIGINT NOT NULL,
	-- Display name such as Work, Family or Meeting room 3.
	"name" VARCHAR(200) NOT NULL,
	-- What belongs on this calendar, shown when someone is asked to subscribe.
	"description" TEXT,
	-- IANA zone used to render all-day events and to resolve floating times on import. A calendar default, overridden per event.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Named colour from a fixed palette, so overlaid calendars stay distinguishable.
	"color" VARCHAR(20) NOT NULL DEFAULT 'blue',
	-- primary | secondary | resource | subscribed. A primary calendar cannot be deleted and is where invitations land; a resource is a room or a piece of equipment, which is why a room booking is just an attendee.
	"kind" VARCHAR(16) NOT NULL DEFAULT 'secondary',
	-- Whether events here count against the owners availability. A holidays calendar you subscribe to should not make you look booked for a week.
	"is_default_busy" BOOLEAN NOT NULL DEFAULT true,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "calendars" IS 'A named container of events and the unit that gets shared. Rooms are modelled as calendars rather than as a separate resource table, so booking a room reuses the invitation and conflict machinery instead of duplicating it.';
COMMENT ON COLUMN "calendars"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "calendars"."owner_id" IS 'Owning account. A resource calendar is owned by whoever administers it.';
COMMENT ON COLUMN "calendars"."name" IS 'Display name such as Work, Family or Meeting room 3.';
COMMENT ON COLUMN "calendars"."description" IS 'What belongs on this calendar, shown when someone is asked to subscribe.';
COMMENT ON COLUMN "calendars"."timezone" IS 'IANA zone used to render all-day events and to resolve floating times on import. A calendar default, overridden per event.';
COMMENT ON COLUMN "calendars"."color" IS 'Named colour from a fixed palette, so overlaid calendars stay distinguishable.';
COMMENT ON COLUMN "calendars"."kind" IS 'primary | secondary | resource | subscribed. A primary calendar cannot be deleted and is where invitations land; a resource is a room or a piece of equipment, which is why a room booking is just an attendee.';
COMMENT ON COLUMN "calendars"."is_default_busy" IS 'Whether events here count against the owners availability. A holidays calendar you subscribe to should not make you look booked for a week.';
COMMENT ON COLUMN "calendars"."created_at" IS 'Creation time.';

CREATE INDEX "idx_calendars_owner_kind"
ON "calendars" ("owner_id", "kind");

CREATE TABLE IF NOT EXISTS "calendar_shares" (
	-- Calendar being shared. Half of the composite primary key.
	"calendar_id" BIGINT,
	-- Account the access is granted to. The other half of the key.
	"grantee_id" BIGINT,
	-- free_busy | reader | writer | owner. free_busy is the important one: it exposes that a slot is taken without revealing what it is, which is what makes cross-company scheduling acceptable at all.
	"role" VARCHAR(16) NOT NULL DEFAULT 'free_busy',
	-- When access was granted.
	"granted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("calendar_id", "grantee_id")
);

COMMENT ON TABLE "calendar_shares" IS 'Per-account access to a calendar. The composite key makes a duplicate grant impossible and the reverse index builds the other calendars panel in one scan.';
COMMENT ON COLUMN "calendar_shares"."calendar_id" IS 'Calendar being shared. Half of the composite primary key.';
COMMENT ON COLUMN "calendar_shares"."grantee_id" IS 'Account the access is granted to. The other half of the key.';
COMMENT ON COLUMN "calendar_shares"."role" IS 'free_busy | reader | writer | owner. free_busy is the important one: it exposes that a slot is taken without revealing what it is, which is what makes cross-company scheduling acceptable at all.';
COMMENT ON COLUMN "calendar_shares"."granted_at" IS 'When access was granted.';

CREATE INDEX "idx_calendar_shares_grantee"
ON "calendar_shares" ("grantee_id");

CREATE TABLE IF NOT EXISTS "events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Calendar the event lives on. An invitation accepted from outside creates a copy on the attendees own calendar, which is why the same meeting can be several rows.
	"calendar_id" BIGINT NOT NULL,
	-- iCalendar UID, stable across systems. Copies of one meeting on different calendars share it, which is how an update from the organiser is matched to the right local row.
	"uid" VARCHAR(255) NOT NULL,
	-- Account that owns the meeting. Null for an event imported from an external system with no matching account.
	"organizer_id" BIGINT,
	-- Summary line. Defaults to Busy so a free-busy export of a private event still has something to render.
	"title" VARCHAR(500) NOT NULL DEFAULT 'Busy',
	-- Agenda or notes.
	"description" TEXT,
	-- Free-text place or a video link. Free text because a room booking is expressed as a resource attendee, not as this field.
	"location" VARCHAR(500),
	-- Start instant in UTC. Stored alongside the zone rather than instead of it, so overlap queries and free-busy never have to convert anything.
	"starts_at" TIMESTAMPTZ NOT NULL,
	-- End instant, exclusive. Half-open intervals mean two back-to-back meetings do not register as a conflict.
	"ends_at" TIMESTAMPTZ NOT NULL,
	-- IANA zone the event was created in. This is the authoritative field: when a government moves a daylight saving boundary, the instant is recomputed from the local time in this zone, not the other way round.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- All-day events are local dates, not instants. A birthday is on the 4th everywhere, so the renderer uses the calendar zone and ignores the stored offset.
	"is_all_day" BOOLEAN NOT NULL DEFAULT false,
	-- confirmed | tentative | cancelled. A cancelled event is kept rather than deleted so the cancellation propagates to attendees who are offline.
	"status" VARCHAR(12) NOT NULL DEFAULT 'confirmed',
	-- default | public | private. Private events still appear as busy to anyone holding free_busy access, with the title suppressed.
	"visibility" VARCHAR(12) NOT NULL DEFAULT 'default',
	-- opaque | transparent. Transparent events do not block availability, which is how an all-day conference marker avoids making someone unbookable.
	"transparency" VARCHAR(12) NOT NULL DEFAULT 'opaque',
	-- Revision counter incremented on every material change. Attendee clients ignore an update whose sequence is not higher, which is what stops a delayed email reviving an old version.
	"sequence" INTEGER NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last change, and the basis for incremental sync tokens.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "events" IS 'A single event, or the definition of a recurring series when a recurrence row exists. The series row stores the first occurrence; every later occurrence is generated, never stored, unless something about it was changed.';
COMMENT ON COLUMN "events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "events"."calendar_id" IS 'Calendar the event lives on. An invitation accepted from outside creates a copy on the attendees own calendar, which is why the same meeting can be several rows.';
COMMENT ON COLUMN "events"."uid" IS 'iCalendar UID, stable across systems. Copies of one meeting on different calendars share it, which is how an update from the organiser is matched to the right local row.';
COMMENT ON COLUMN "events"."organizer_id" IS 'Account that owns the meeting. Null for an event imported from an external system with no matching account.';
COMMENT ON COLUMN "events"."title" IS 'Summary line. Defaults to Busy so a free-busy export of a private event still has something to render.';
COMMENT ON COLUMN "events"."description" IS 'Agenda or notes.';
COMMENT ON COLUMN "events"."location" IS 'Free-text place or a video link. Free text because a room booking is expressed as a resource attendee, not as this field.';
COMMENT ON COLUMN "events"."starts_at" IS 'Start instant in UTC. Stored alongside the zone rather than instead of it, so overlap queries and free-busy never have to convert anything.';
COMMENT ON COLUMN "events"."ends_at" IS 'End instant, exclusive. Half-open intervals mean two back-to-back meetings do not register as a conflict.';
COMMENT ON COLUMN "events"."timezone" IS 'IANA zone the event was created in. This is the authoritative field: when a government moves a daylight saving boundary, the instant is recomputed from the local time in this zone, not the other way round.';
COMMENT ON COLUMN "events"."is_all_day" IS 'All-day events are local dates, not instants. A birthday is on the 4th everywhere, so the renderer uses the calendar zone and ignores the stored offset.';
COMMENT ON COLUMN "events"."status" IS 'confirmed | tentative | cancelled. A cancelled event is kept rather than deleted so the cancellation propagates to attendees who are offline.';
COMMENT ON COLUMN "events"."visibility" IS 'default | public | private. Private events still appear as busy to anyone holding free_busy access, with the title suppressed.';
COMMENT ON COLUMN "events"."transparency" IS 'opaque | transparent. Transparent events do not block availability, which is how an all-day conference marker avoids making someone unbookable.';
COMMENT ON COLUMN "events"."sequence" IS 'Revision counter incremented on every material change. Attendee clients ignore an update whose sequence is not higher, which is what stops a delayed email reviving an old version.';
COMMENT ON COLUMN "events"."created_at" IS 'Creation time.';
COMMENT ON COLUMN "events"."updated_at" IS 'Last change, and the basis for incremental sync tokens.';

CREATE INDEX "idx_events_calendar_start"
ON "events" ("calendar_id", "starts_at");
CREATE UNIQUE INDEX "uq_events_uid_calendar"
ON "events" ("uid", "calendar_id");
CREATE INDEX "idx_events_calendar_sync"
ON "events" ("calendar_id", "updated_at");

CREATE TABLE IF NOT EXISTS "event_recurrences" (
	-- The series this rule expands. A one-to-one with events, so the presence of a row here is exactly what makes an event recurring.
	"event_id" BIGINT,
	-- RFC 5545 rule such as FREQ=WEEKLY;BYDAY=TU;INTERVAL=2. Kept as the original string because it is what round-trips to and from every other calendar system; the parsed columns beside it exist only to make queries possible.
	"rrule" VARCHAR(500) NOT NULL,
	-- daily | weekly | monthly | yearly. Parsed out of the rule so the expander can pick a strategy without re-parsing.
	"freq" VARCHAR(12) NOT NULL,
	-- Repeat every N periods.
	"interval_count" SMALLINT NOT NULL DEFAULT 1,
	-- Last instant the series can produce an occurrence. Null for an endless series or one bounded by a count.
	"until_at" TIMESTAMPTZ,
	-- Bound as a number of occurrences instead of a date. Exactly one of this and until_at is set, or neither for a series with no end.
	"occurrence_count" INTEGER,
	-- How far the series has been expanded into the free-busy index. An endless series has to stop somewhere, and this is the watermark a background job advances.
	"horizon_at" TIMESTAMPTZ,
	PRIMARY KEY("event_id")
);

COMMENT ON TABLE "event_recurrences" IS 'The recurrence rule of one series. Storing the rule rather than the occurrences is what keeps a daily standup from being a hundred thousand rows and what makes editing the whole series a single update.';
COMMENT ON COLUMN "event_recurrences"."event_id" IS 'The series this rule expands. A one-to-one with events, so the presence of a row here is exactly what makes an event recurring.';
COMMENT ON COLUMN "event_recurrences"."rrule" IS 'RFC 5545 rule such as FREQ=WEEKLY;BYDAY=TU;INTERVAL=2. Kept as the original string because it is what round-trips to and from every other calendar system; the parsed columns beside it exist only to make queries possible.';
COMMENT ON COLUMN "event_recurrences"."freq" IS 'daily | weekly | monthly | yearly. Parsed out of the rule so the expander can pick a strategy without re-parsing.';
COMMENT ON COLUMN "event_recurrences"."interval_count" IS 'Repeat every N periods.';
COMMENT ON COLUMN "event_recurrences"."until_at" IS 'Last instant the series can produce an occurrence. Null for an endless series or one bounded by a count.';
COMMENT ON COLUMN "event_recurrences"."occurrence_count" IS 'Bound as a number of occurrences instead of a date. Exactly one of this and until_at is set, or neither for a series with no end.';
COMMENT ON COLUMN "event_recurrences"."horizon_at" IS 'How far the series has been expanded into the free-busy index. An endless series has to stop somewhere, and this is the watermark a background job advances.';

CREATE TABLE IF NOT EXISTS "recurrence_exceptions" (
	-- Series the date is removed from. Half of the composite primary key.
	"event_id" BIGINT,
	-- The occurrence start the rule would have produced. The other half of the key, and the identity of an occurrence throughout this schema.
	"original_start_at" TIMESTAMPTZ,
	-- When the deletion happened, needed so a sync client can tell that a previously visible occurrence has gone.
	"excluded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("event_id", "original_start_at")
);

COMMENT ON TABLE "recurrence_exceptions" IS 'The EXDATE set: occurrences deleted outright. Kept as its own table rather than as a cancelled override because it maps directly to the iCalendar property, which is what makes export lossless.';
COMMENT ON COLUMN "recurrence_exceptions"."event_id" IS 'Series the date is removed from. Half of the composite primary key.';
COMMENT ON COLUMN "recurrence_exceptions"."original_start_at" IS 'The occurrence start the rule would have produced. The other half of the key, and the identity of an occurrence throughout this schema.';
COMMENT ON COLUMN "recurrence_exceptions"."excluded_at" IS 'When the deletion happened, needed so a sync client can tell that a previously visible occurrence has gone.';

CREATE TABLE IF NOT EXISTS "event_overrides" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Series being overridden.
	"event_id" BIGINT NOT NULL,
	-- The occurrence this replaces, identified by the start the rule would have produced. This is the RECURRENCE-ID, and it never changes even when the override moves the meeting to another day.
	"original_start_at" TIMESTAMPTZ NOT NULL,
	-- New start. Null means keep the generated one, so an override that only changes the title carries no times at all.
	"starts_at" TIMESTAMPTZ,
	-- New end. Null means unchanged.
	"ends_at" TIMESTAMPTZ,
	-- Overridden summary. Null means inherit from the series.
	"title" VARCHAR(500),
	-- Overridden location. Null means inherit.
	"location" VARCHAR(500),
	-- Overridden notes. Null means inherit.
	"description" TEXT,
	-- Overridden status, typically cancelled for a single skipped week when the client prefers a cancellation to an EXDATE. Null means inherit.
	"status" VARCHAR(12),
	-- Last change to this occurrence, used by incremental sync.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "event_overrides" IS 'A single occurrence that differs from its series: this Tuesday moved an hour later, that one renamed. Every column is nullable and null means inherit, so an override is a sparse patch rather than a copy that silently stops tracking series edits.';
COMMENT ON COLUMN "event_overrides"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "event_overrides"."event_id" IS 'Series being overridden.';
COMMENT ON COLUMN "event_overrides"."original_start_at" IS 'The occurrence this replaces, identified by the start the rule would have produced. This is the RECURRENCE-ID, and it never changes even when the override moves the meeting to another day.';
COMMENT ON COLUMN "event_overrides"."starts_at" IS 'New start. Null means keep the generated one, so an override that only changes the title carries no times at all.';
COMMENT ON COLUMN "event_overrides"."ends_at" IS 'New end. Null means unchanged.';
COMMENT ON COLUMN "event_overrides"."title" IS 'Overridden summary. Null means inherit from the series.';
COMMENT ON COLUMN "event_overrides"."location" IS 'Overridden location. Null means inherit.';
COMMENT ON COLUMN "event_overrides"."description" IS 'Overridden notes. Null means inherit.';
COMMENT ON COLUMN "event_overrides"."status" IS 'Overridden status, typically cancelled for a single skipped week when the client prefers a cancellation to an EXDATE. Null means inherit.';
COMMENT ON COLUMN "event_overrides"."updated_at" IS 'Last change to this occurrence, used by incremental sync.';

CREATE UNIQUE INDEX "uq_event_overrides_occurrence"
ON "event_overrides" ("event_id", "original_start_at");

CREATE TABLE IF NOT EXISTS "event_attendees" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Series or single event invited to.
	"event_id" BIGINT NOT NULL,
	-- Set when the response applies to one occurrence only, such as declining a single standup. Null means the response covers the whole series.
	"override_id" BIGINT,
	-- Account, when the invitee has one. Null for an external guest who was invited by address.
	"user_id" BIGINT,
	-- Invited address, stored even when user_id is set. It is the identity the iCalendar reply is matched on, and it must survive the guest changing their account email.
	"email" VARCHAR(320) NOT NULL,
	-- Name as supplied by the organiser, shown until the invitee has an account.
	"display_name" VARCHAR(160),
	-- required | optional | chair | resource. A resource is a room calendar, which is how a booking conflict surfaces as an ordinary decline.
	"role" VARCHAR(16) NOT NULL DEFAULT 'required',
	-- needs_action | accepted | declined | tentative. needs_action is the default rather than a null so the awaiting-reply count is a plain equality filter.
	"rsvp_status" VARCHAR(16) NOT NULL DEFAULT 'needs_action',
	-- Note sent with the reply, which is usually the reason for a decline.
	"comment" VARCHAR(500),
	-- When the invitee answered. Null while awaiting a reply, and the basis for the nudge reminder.
	"responded_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "event_attendees" IS 'One invitee of one meeting. Attendees hang off the series by default and off an override only when someone declines a single occurrence, which keeps a weekly meeting with twelve people at twelve rows instead of twelve per week.';
COMMENT ON COLUMN "event_attendees"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "event_attendees"."event_id" IS 'Series or single event invited to.';
COMMENT ON COLUMN "event_attendees"."override_id" IS 'Set when the response applies to one occurrence only, such as declining a single standup. Null means the response covers the whole series.';
COMMENT ON COLUMN "event_attendees"."user_id" IS 'Account, when the invitee has one. Null for an external guest who was invited by address.';
COMMENT ON COLUMN "event_attendees"."email" IS 'Invited address, stored even when user_id is set. It is the identity the iCalendar reply is matched on, and it must survive the guest changing their account email.';
COMMENT ON COLUMN "event_attendees"."display_name" IS 'Name as supplied by the organiser, shown until the invitee has an account.';
COMMENT ON COLUMN "event_attendees"."role" IS 'required | optional | chair | resource. A resource is a room calendar, which is how a booking conflict surfaces as an ordinary decline.';
COMMENT ON COLUMN "event_attendees"."rsvp_status" IS 'needs_action | accepted | declined | tentative. needs_action is the default rather than a null so the awaiting-reply count is a plain equality filter.';
COMMENT ON COLUMN "event_attendees"."comment" IS 'Note sent with the reply, which is usually the reason for a decline.';
COMMENT ON COLUMN "event_attendees"."responded_at" IS 'When the invitee answered. Null while awaiting a reply, and the basis for the nudge reminder.';

CREATE UNIQUE INDEX "uq_event_attendees_event_email"
ON "event_attendees" ("event_id", "email");
CREATE INDEX "idx_event_attendees_user_status"
ON "event_attendees" ("user_id", "rsvp_status");
CREATE INDEX "idx_event_attendees_override"
ON "event_attendees" ("override_id");

CREATE TABLE IF NOT EXISTS "event_reminders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Event the reminder belongs to.
	"event_id" BIGINT NOT NULL,
	-- Whose reminder this is. Null for a reminder the organiser set on the event for everyone, which each attendee may then override.
	"user_id" BIGINT,
	-- popup | email | push.
	"method" VARCHAR(12) NOT NULL DEFAULT 'popup',
	-- Offset from the occurrence start, so one row covers every occurrence of a series. An absolute time would have to be recomputed on every rule change.
	"minutes_before" INTEGER NOT NULL,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "event_reminders" IS 'A relative alert. Storing an offset rather than a fire time is what makes a reminder survive the meeting being moved, and lets the scheduler compute due alerts from the occurrence index instead of rewriting rows.';
COMMENT ON COLUMN "event_reminders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "event_reminders"."event_id" IS 'Event the reminder belongs to.';
COMMENT ON COLUMN "event_reminders"."user_id" IS 'Whose reminder this is. Null for a reminder the organiser set on the event for everyone, which each attendee may then override.';
COMMENT ON COLUMN "event_reminders"."method" IS 'popup | email | push.';
COMMENT ON COLUMN "event_reminders"."minutes_before" IS 'Offset from the occurrence start, so one row covers every occurrence of a series. An absolute time would have to be recomputed on every rule change.';
COMMENT ON COLUMN "event_reminders"."created_at" IS 'Creation time.';

CREATE INDEX "idx_event_reminders_event_user"
ON "event_reminders" ("event_id", "user_id");

CREATE TABLE IF NOT EXISTS "working_hours" (
	-- Whose availability this describes. Half of the composite primary key.
	"user_id" BIGINT,
	-- Day of the week, 0 for Monday. The other half of the key, so a day has one window and a split day is expressed by two calendars rather than two rows.
	"weekday" SMALLINT,
	-- Start of the working window as a local wall-clock time, deliberately not an instant. Nine in the morning stays nine in the morning across a daylight saving change.
	"starts_at_local" TIME NOT NULL,
	-- End of the window, exclusive.
	"ends_at_local" TIME NOT NULL,
	-- Zone the local times are read in. Stored here rather than taken from the user so a contractor working European hours from another continent is expressible.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- False marks a non-working day, which keeps the weekend as an explicit statement rather than the absence of a row.
	"is_available" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("user_id", "weekday")
);

COMMENT ON TABLE "working_hours" IS 'Recurring availability, the frame that suggested meeting times are searched within. It is not a calendar of events: nothing here blocks time, it only says when someone is willing to be booked.';
COMMENT ON COLUMN "working_hours"."user_id" IS 'Whose availability this describes. Half of the composite primary key.';
COMMENT ON COLUMN "working_hours"."weekday" IS 'Day of the week, 0 for Monday. The other half of the key, so a day has one window and a split day is expressed by two calendars rather than two rows.';
COMMENT ON COLUMN "working_hours"."starts_at_local" IS 'Start of the working window as a local wall-clock time, deliberately not an instant. Nine in the morning stays nine in the morning across a daylight saving change.';
COMMENT ON COLUMN "working_hours"."ends_at_local" IS 'End of the window, exclusive.';
COMMENT ON COLUMN "working_hours"."timezone" IS 'Zone the local times are read in. Stored here rather than taken from the user so a contractor working European hours from another continent is expressible.';
COMMENT ON COLUMN "working_hours"."is_available" IS 'False marks a non-working day, which keeps the weekend as an explicit statement rather than the absence of a row.';

CREATE TABLE IF NOT EXISTS "busy_intervals" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account the interval blocks. Derived from calendar ownership and sharing at write time, so a free-busy read never has to resolve permissions.
	"user_id" BIGINT NOT NULL,
	-- Event that produced the interval. Null for a block imported from an external free-busy feed, where no event details are available.
	"event_id" BIGINT,
	-- The occurrence this row expands, matching original_start_at in the override model so a single changed week updates exactly one interval.
	"occurrence_start_at" TIMESTAMPTZ NOT NULL,
	-- Interval start after recurrence expansion and overrides are applied.
	"starts_at" TIMESTAMPTZ NOT NULL,
	-- Interval end, exclusive, so touching meetings are not conflicts.
	"ends_at" TIMESTAMPTZ NOT NULL,
	-- True for a tentative acceptance, which should soft-block a slot rather than rule it out entirely.
	"is_tentative" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "busy_intervals" IS 'The materialised occurrence index, and the only place recurring events are ever stored expanded. Finding a free slot for eight people is one range scan here rather than eight rule expansions, and it is rebuilt incrementally whenever a series, exception or override changes.';
COMMENT ON COLUMN "busy_intervals"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "busy_intervals"."user_id" IS 'Account the interval blocks. Derived from calendar ownership and sharing at write time, so a free-busy read never has to resolve permissions.';
COMMENT ON COLUMN "busy_intervals"."event_id" IS 'Event that produced the interval. Null for a block imported from an external free-busy feed, where no event details are available.';
COMMENT ON COLUMN "busy_intervals"."occurrence_start_at" IS 'The occurrence this row expands, matching original_start_at in the override model so a single changed week updates exactly one interval.';
COMMENT ON COLUMN "busy_intervals"."starts_at" IS 'Interval start after recurrence expansion and overrides are applied.';
COMMENT ON COLUMN "busy_intervals"."ends_at" IS 'Interval end, exclusive, so touching meetings are not conflicts.';
COMMENT ON COLUMN "busy_intervals"."is_tentative" IS 'True for a tentative acceptance, which should soft-block a slot rather than rule it out entirely.';

CREATE INDEX "idx_busy_intervals_user_window"
ON "busy_intervals" ("user_id", "starts_at", "ends_at");
CREATE INDEX "idx_busy_intervals_event_occurrence"
ON "busy_intervals" ("event_id", "occurrence_start_at");

ALTER TABLE "calendars"
ADD FOREIGN KEY("owner_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "calendar_shares"
ADD FOREIGN KEY("calendar_id") REFERENCES "calendars"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
